void Equal(const std::vector<float>& a,const std::vector<float>& b){Need(a.size()==b.size(),"Q/O extent mismatch");for(auto v:b)Need(std::isfinite(v),"Nonfinite/unwritten Q/O value");Need(std::memcmp(a.data(),b.data(),a.size()*4)==0,"Q/O complete output bits differ");}
struct Weight {AffineInt4Layout layout;std::vector<uint32_t> words;std::vector<uint16_t> scales,biases;MetalAffineInt4Weight gpu;};
Weight Make(MetalContext& gpu,uint32_t& seed,bool edge){Weight w;w.layout=AffineInt4Layout::Create(4096,4096,AffineInt4CoefficientType::FP16);w.words.resize(w.layout.weightBytes/4);w.scales.resize(w.layout.coefficientBytes/2);w.biases.resize(w.scales.size());for(auto& v:w.words){seed=1664525u*seed+1013904223u;v=seed;}for(size_t i=0;i<w.scales.size();++i){w.scales[i]=Float32ToFloat16RNE(float(int((i+seed)%13)-6)*.00171f);w.biases[i]=Float32ToFloat16RNE(float(int((i+seed)%17)-8)*.00313f);}if(edge)for(size_t i=0;i<w.scales.size();i+=131){w.scales[i]=i%2?0:0x8000;w.biases[i]=i%3?0x1400:0x9400;}w.gpu=gpu.UploadAffineInt4(w.words.data(),w.layout.weightBytes,w.scales.data(),w.layout.coefficientBytes,w.biases.data(),w.layout.coefficientBytes,4096,4096,true);return w;}
JSON Oracle(const Weight& w,const std::vector<float>& input,const std::vector<float>& ref,const std::vector<float>& got,size_t rows){AffineInt4View view(w.layout,w.words.data(),w.layout.weightBytes,w.scales.data(),w.layout.coefficientBytes,w.biases.data(),w.layout.coefficientBytes);std::vector<float> decoded(4096);JSON out=JSON::array();for(size_t col:std::set<size_t>{0,1,15,16,31,32,63,64,2048,4095}){view.DecodeRow(col,decoded.data(),4096);for(size_t row:std::set<size_t>{0,511,rows/2,rows-1}){double total=0,absolute=0;for(size_t k=0;k<4096;++k){double v=double(Float16ToFloat32(Float32ToFloat16RNE(input[row*4096+k])))*Float16ToFloat32(Float32ToFloat16RNE(decoded[k]));total+=v;absolute+=std::abs(v);}for(auto value:{ref[row*4096+col],got[row*4096+col]})Need(std::abs(double(value)-total)<=2e-6+4e-6*absolute,"Unchanged FP64 Q/O sample bound failed");out.push_back(JSON{{"row",row},{"column",col},{"sum",total},{"sum_abs",absolute}});}}return out;}
