 auto original=gpu.Upload(input,rows,n),normOwner=gpu.Upload(normInit,rows+2,n),resOwner=gpu.Upload(resInit,rows+2,n);auto norm=gpu.PrepareDiagnosticDenseView(normOwner,n,rows,n),res=gpu.PrepareDiagnosticDenseView(resOwner,n,rows,n);auto qRef=gpu.Allocate(rows,n),ctxRef=gpu.Allocate(rows,n),oRef=gpu.Allocate(rows,n),finalRef=gpu.Allocate(rows,n);gpu.Zero(qRef);gpu.Zero(ctxRef);gpu.Zero(oRef);gpu.Zero(finalRef);
