 Need(gpu.PrepareDiagnosticBulkAffine(norm,q.gpu,res)&&gpu.PrepareDiagnosticBulkAffine(norm,o.gpu,res),"Cannot prepare bounded Q/O products");Reject([&]{gpu.PrepareDiagnosticBulkAffine(norm,q.gpu,norm);});gpu.Begin();Reject([&]{gpu.EncodeAdd(original,res,res);});gpu.Abort();const auto owners=MetalContext::ProfileOwnerStats();const auto plans=gpu.PackedAffinePlanCount(),pipes=gpu.AffineProfilePipelineCount();
 gpu.Begin();for(size_t c=0;c<chunks;++c){gpu.EncodeAffineInt4MatMul(inputViews[c],q.gpu,qViews[c]);gpu.EncodeAdd(qViews[c],inputViews[c],ctxViews[c]);}for(size_t c=0;c<chunks;++c){gpu.EncodeAffineInt4MatMul(ctxViews[c],o.gpu,oViews[c]);gpu.EncodeAdd(inputViews[c],oViews[c],finalViews[c]);}gpu.SubmitAndWait();Need(gpu.LastPackedAffineDispatches()==2*chunks&&gpu.LastDiagnosticBulkDispatches()==0&&gpu.LastAffineProfileDispatches()==2*chunks&&gpu.LastAffineProfileMisses()==0,"Original Q/O route differs");auto qr=gpu.Download(qRef),cr=gpu.Download(ctxRef),orr=gpu.Download(oRef),fr=gpu.Download(finalRef);
 auto contexts=[&](bool skip){gpu.EncodeDiagnosticBulkAffine(norm,q.gpu,res);for(size_t c=0;c<chunks;++c)if(!skip||c+1<chunks)gpu.EncodeAdd(resViews[c],inputViews[c],normViews[c]);};
 gpu.Begin();contexts(false);gpu.SubmitAndWait();Need(gpu.LastDiagnosticBulkDispatches()==1&&gpu.LastPackedAffineDispatches()==0,"Q/context probe route differs");auto qGot=gpu.Download(res),ctxGot=gpu.Download(norm),contextWords=gpu.Download(normOwner);Equal(qr,qGot);Equal(cr,ctxGot);
 auto chain=[&](bool skip){contexts(skip);gpu.EncodeDiagnosticBulkAffine(norm,o.gpu,res);gpu.EncodeAdd(original,res,norm);};
 gpu.Update(normOwner,normInit);gpu.Update(resOwner,resInit);gpu.Begin();chain(false);Reject([&]{gpu.Download(resOwner);});gpu.SubmitAndWait();Need(gpu.LastDiagnosticBulkDispatches()==2&&gpu.LastPackedAffineDispatches()==0,"Alias chain route differs");auto finalGot=gpu.Download(norm),oGot=gpu.Download(res),finalWords=gpu.Download(normOwner),resWords=gpu.Download(resOwner);Equal(fr,finalGot);Equal(orr,oGot);for(const auto& parent:{finalWords,resWords})for(size_t j=0;j<n;++j)Need(parent[j]==front&&parent[parent.size()-n+j]==back,"Q/O parent guard overwritten");
